<template><main class="page"><section class="shell"><header><div><div class="logo">CL</div><p class="eyebrow">CareLink Pharmacie</p><h1>Portail officinal</h1><p>Stocks, commandes et ordonnances électroniques.</p></div><button class="btn" v-if="user" @click="signOut">Déconnexion</button></header><div v-if="!user" class="auth"><h2>Connexion</h2><input v-model="email" type="email" placeholder="Email"><input v-model="password" type="password" placeholder="Mot de passe"><button class="primary" @click="signIn">Se connecter</button><small v-if="error">{{error}}</small></div><div v-else><div class="stats"><div><b>{{pharmacy?.name||'—'}}</b><span>Officine</span></div><div><b>{{products.length}}</b><span>Produits en stock</span></div><div><b>{{orders.length}}</b><span>Commandes actives</span></div></div><section class="card"><h2>Ordonnances à traiter</h2><div v-for="t in rxTransfers" :key="t.id" class="row"><div><b>{{t.prescriptions?.prescription_code}}</b><p>{{t.patient?.first_name}} {{t.patient?.last_name}} · {{t.status}}</p><small v-if="t.patient_notes">Note : {{t.patient_notes}}</small></div><div class="actions"><button class="primary" v-if="t.status==='pending'" @click="respondRx(t.id,'accepted')">Accepter</button><button class="secondary" v-if="t.status==='accepted'" @click="respondRx(t.id,'dispensing')">Préparer</button><button class="accept" v-if="t.status==='dispensing'" @click="respondRx(t.id,'completed')">Délivrée</button><button class="reject" v-if="['pending','accepted'].includes(t.status)" @click="respondRx(t.id,'rejected')">Refuser</button></div></div><div v-if="!rxTransfers.length" class="empty">Aucune ordonnance à traiter.</div></section><section class="card"><h2>Commandes à traiter</h2><div v-for="o in orders" :key="o.id" class="row"><div><b>{{o.orders?.order_number||o.order_id}}</b><p>{{o.status}}</p></div><div class="actions"><button class="primary" v-if="o.status==='pending'" @click="updateOrder(o.id,'accepted')">Accepter</button><button class="secondary" v-if="o.status==='accepted'" @click="updateOrder(o.id,'preparing')">Préparer</button><button class="accept" v-if="o.status==='preparing'" @click="updateOrder(o.id,'ready_for_pickup')">Prête</button><button class="accept" v-if="o.status==='ready_for_pickup'" @click="updateOrder(o.id,'completed')">Délivrée</button><button class="reject" v-if="o.status==='pending'" @click="updateOrder(o.id,'rejected')">Refuser</button></div></div><div v-if="!orders.length" class="empty">Aucune commande en attente.</div></section><section class="card"><h2>Stock</h2><div v-for="p in products" :key="p.id" class="row"><span>{{p.name}}</span><b>{{p.product_stocks?.[0]?.current_quantity??0}}</b></div></section></div></section></main></template>
<script setup lang="ts">import {ref} from 'vue';import {createClient} from '@supabase/supabase-js';const supabase=createClient(import.meta.env.VITE_SUPABASE_URL,import.meta.env.VITE_SUPABASE_ANON_KEY);const user=ref<any>(),email=ref(''),password=ref(''),error=ref(''),pharmacy=ref<any>(),products=ref<any[]>([]),orders=ref<any[]>([]),rxTransfers=ref<any[]>([]);async function signIn(){const r=await supabase.auth.signInWithPassword({email:email.value,password:password.value});if(r.error){error.value=r.error.message;return}user.value=r.data.user;await load()}async function load(){const st=await supabase.from('pharmacy_staff').select('pharmacy_id,pharmacies(*)').eq('profile_id',user.value.id).eq('is_active',true).limit(1).single();pharmacy.value=st.data?.pharmacies;if(!pharmacy.value)return;const p=await supabase.from('products').select('id,name,product_stocks(current_quantity)').eq('pharmacy_id',pharmacy.value.id).eq('is_active',true).limit(100);products.value=p.data||[];const o=await supabase.from('order_fulfillments').select('*,orders(order_number)').eq('pharmacy_id',pharmacy.value.id).in('status',['pending','accepted','preparing','ready_for_pickup']).order('created_at',{ascending:false});orders.value=o.data||[];const rx=await supabase.from('prescription_pharmacy_transfers').select('id,status,patient_notes,patient:profiles!prescription_pharmacy_transfers_patient_id_fkey(first_name,last_name),prescriptions(prescription_code)').eq('pharmacy_id',pharmacy.value.id).in('status',['pending','accepted','dispensing']).order('created_at',{ascending:false});rxTransfers.value=rx.data||[]}async function updateOrder(id:string,status:string){const {error:e}=await supabase.rpc('update_pharmacy_fulfillment',{p_fulfillment_id:id,p_status:status});if(e)error.value=e.message;await load()}async function respondRx(id:string,status:string){const {error:e}=await supabase.rpc('respond_to_prescription_transfer',{p_transfer_id:id,p_status:status,p_response_notes:null});if(e)error.value=e.message;await load()}async function signOut(){await supabase.auth.signOut();user.value=null}supabase.auth.getSession().then(async r=>{user.value=r.data.session?.user;if(user.value)await load()})</script>
<style>:root{font-family:Inter,system-ui,sans-serif;color:#102a43;background:#f5f8fc}*{box-sizing:border-box}body{margin:0}.page{min-height:100vh;padding:28px;background:linear-gradient(135deg,#eefbf8,#f5fbff)}.shell{max-width:1100px;margin:auto}header{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:28px}.logo{width:52px;height:52px;display:grid;place-items:center;border-radius:16px;color:#fff;font-weight:800;background:linear-gradient(135deg,#0aa38c,#1677e8)}.eyebrow{font-weight:700;color:#0a8f7a;margin:16px 0 4px}h1{font-size:clamp(2rem,6vw,3.2rem);margin:0}.auth,.card{background:#fff;padding:24px;border-radius:18px;box-shadow:0 10px 30px #14467814;margin-bottom:20px}.auth{max-width:460px}.auth input{display:block;width:100%;padding:12px;margin:10px 0;border:1px solid #d8e0ea;border-radius:10px}.primary,.btn{border:0;border-radius:10px;padding:11px 16px;cursor:pointer}.primary{background:#0a8f7a;color:#fff}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:20px}.stats div{background:#fff;padding:20px;border-radius:16px}.stats b,.stats span{display:block}.stats b{font-size:1.5rem}.stats span{color:#64748b}.row{display:flex;justify-content:space-between;gap:20px;padding:14px 0;border-bottom:1px solid #e2e8f0}.row p{margin:4px 0;color:#64748b}.empty{padding:20px;color:#64748b}@media(max-width:700px){.stats{grid-template-columns:1fr}.row{flex-direction:column}} .actions{display:flex;gap:8px;flex-wrap:wrap}.accept{background:#0b8f67;color:#fff}.reject{background:#fff0f0;color:#b42318}.pharmacy-transfer{margin-top:16px;padding-top:12px;border-top:1px solid #e2e8f0}.input{width:100%;padding:10px;border:1px solid #d8e0ea;border-radius:10px;margin:6px 0}</style>
